import unittest
from solution import combine_intervals

class T(unittest.TestCase):
    def test_overlap(self):
        self.assertEqual(combine_intervals([[1, 3], [2, 6]]), [[1, 6]])
    def test_touch(self):
        self.assertEqual(combine_intervals([[1, 3], [3, 5]]), [[1, 5]])
    def test_disjoint(self):
        self.assertEqual(combine_intervals([[5, 6], [1, 2]]), [[1, 2], [5, 6]])
    def test_empty(self):
        self.assertEqual(combine_intervals([]), [])
